    {selected === "case" && <section className="audit-timeline-panel" aria-label="Shared case detail and timeline"><div className="section-heading"><div><span className="section-kicker">{caseRecord.caseId} · v{caseRecord.caseVersion} · {caseRecord.slaState}</span><h2>{caseRecord.title}</h2></div><label>Entry type <select value={caseEntryType} onChange={(event)=>setCaseEntryType(event.target.value as "ALL" | CaseEntryType)}><option value="ALL">All entries</option>{[...new Set(caseTimeline.map(({entryType})=>entryType))].map((entryType)=><option key={entryType} value={entryType}>{entryType}</option>)}</select></label></div><div className="case-facts"><span><b>{caseRecord.state}</b> lifecycle state</span><span><b>{caseRecord.ownerId ?? "Unassigned"}</b> owner</span><span><b>{caseRecord.severity.integrity}</b> integrity severity</span><span><b>{caseRecord.linkedEntities.providerReceiptId}</b> linked receipt</span></div><div className="spread-action-row"><button type="button" disabled={caseRecord.state === "CLOSED"} onClick={advanceCase}>{caseActionLabel}</button>{(caseRecord.state === "INVESTIGATING" || caseRecord.state === "PENDING_ACTION") && <button type="button" onClick={recordCaseNote}>Record investigator note</button>}</div>{caseAction !== "idle" && <div className={`customer-review-result customer-review-result--${caseAction === "denied" ? "denied" : "submitted"}`} role="status"><strong>{caseAction === "denied" ? "Action denied" : "Case history appended"}</strong><span>{caseAction === "denied" ? "This role cannot perform the requested case transition." : "The previous version remains immutable and evidence-linked."}</span></div>}<div className="audit-timeline-grid"><ol className="timeline">{filteredCaseEntries.map((caseEntry)=><li key={caseEntry.entryId}><div className="audit-event-button"><span className="timeline-mark timeline-mark--done">✓</span><div><strong>{caseEntry.entryType}</strong><span>{caseEntry.actorId} · {caseEntry.outcome} · {caseEntry.reasonCode}</span><time>{caseEntry.occurredAt}</time></div></div></li>)}</ol><aside><span className="section-kicker">Case Copilot · cited</span><h3>{caseSummary.status === "SUPPORTED" ? "Evidence-linked summary" : "Insufficient evidence"}</h3><p>{caseSummary.summary}</p><small>{caseSummary.status === "SUPPORTED" ? `Confidence ${caseSummary.confidenceBps/100}% · ` : ""}{caseSummary.citations.join(" · ")}</small><div className="pricing-integrity"><LockKeyhole size={15}/><span>Investigator notes are untrusted input. AI cannot execute tools or advance the case.</span></div></aside></div></section>}
    {selected === "catalogue" && <section className="audit-timeline-panel" aria-label="Seeded domain case queue"><div className="section-heading"><div><span className="section-kicker">Synthetic seeded cases · tenant scoped</span><h2>Governed case queue</h2></div><label>Domain <select value={caseDomain} onChange={(event)=>setCaseDomain(event.target.value as "ALL" | SharedCase["domain"])}><option value="ALL">All domains</option>{[...new Set(seededDomainCases.map(({domain})=>domain))].map((domain)=><option key={domain} value={domain}>{domain}</option>)}</select></label></div><div className="case-facts"><span><b>{visibleSeededCases.length}</b> visible cases</span><span><b>{new Set(visibleSeededCases.map(({domain})=>domain)).size}</b> domains</span><span><b>{visibleSeededCases.filter(({severity})=>Object.values(severity).includes("HIGH")).length}</b> high dimension</span><span><b>{visibleSeededCases.filter(({ownerId})=>ownerId === null).length}</b> unassigned</span></div><div className="seeded-case-list">{visibleSeededCases.map((seededCase)=><button type="button" key={seededCase.caseId} onClick={()=>openSeededCase(seededCase)}><span><strong>{seededCase.title}</strong><small>{seededCase.caseId} · {seededCase.domain} · {seededCase.provenance}</small></span><span><b>{seededCase.state}</b><small>{seededCase.ownerTeam} · {seededCase.slaState}</small></span><span><b>{seededCase.severity.integrity}</b><small>Integrity severity</small></span><i>Open shared detail →</i></button>)}</div><div className="pricing-integrity"><LockKeyhole size={15}/><span>Counts reconcile only to visible tenant-scoped seeds. No real allegation, legal conclusion or live provider action is represented.</span></div></section>}
    {selected === "alerts" && <section className="audit-timeline-panel" aria-label="Governed alert queue"><div className="section-heading"><div><span className="section-kicker">Synthetic alerts · tenant scoped</span><h2>Acknowledge, assign and resolve</h2></div><label>Domain <select value={alertDomain} onChange={(event)=>setAlertDomain(event.target.value as "ALL" | GovernedAlert["domain"])}><option value="ALL">All domains</option>{[...new Set(alerts.map(({domain})=>domain))].map((domain)=><option key={domain} value={domain}>{domain}</option>)}</select></label></div><div className="case-facts"><span><b>{visibleAlerts.length}</b> visible alerts</span><span><b>{visibleAlerts.filter(({state})=>state === "OPEN").length}</b> open</span><span><b>{visibleAlerts.filter(({state})=>state === "ASSIGNED").length}</b> assigned</span><span><b>{visibleAlerts.filter(({state})=>state === "RESOLVED").length}</b> resolved</span></div><div className="alert-layout"><div className="seeded-case-list">{visibleAlerts.map((alert)=><button type="button" className={selectedAlert.alertId === alert.alertId ? "seeded-case-selected" : ""} key={alert.alertId} onClick={()=>{setSelectedAlertId(alert.alertId);setAlertAction("idle");}}><span><strong>{alert.title}</strong><small>{alert.alertId} · {alert.domain} · linked {alert.linkedCaseId}</small></span><span><b>{alert.state}</b><small>{alert.ownerId ?? alert.ownerTeam}</small></span><span><b>{alert.severity}</b><small>{alert.slaState}</small></span><i>Inspect →</i></button>)}</div><aside className="alert-detail"><span className="section-kicker">Selected alert · v{selectedAlert.alertVersion}</span><h3>{selectedAlert.title}</h3><dl><div><dt>State / owner</dt><dd>{selectedAlert.state} · {selectedAlert.ownerId ?? "Unassigned"}</dd></div><div><dt>Reason</dt><dd>{selectedAlert.reasonCodes.join(" · ")}</dd></div><div><dt>Due / SLA</dt><dd>{selectedAlert.dueAt} · {selectedAlert.slaState}</dd></div><div><dt>Resolution requirement</dt><dd>{selectedAlert.resolutionRequirement}</dd></div></dl><div className="spread-action-row"><button type="button" disabled={selectedAlert.state === "RESOLVED"} onClick={advanceAlert}>{alertActionLabel}</button><button type="button" onClick={openAlertCase}>Open linked case</button></div>{alertAction !== "idle" && <div className={`customer-review-result customer-review-result--${alertAction === "denied" ? "denied" : "submitted"}`} role="status"><strong>{alertAction === "denied" ? "Action denied" : "Alert history appended"}</strong><span>{alertAction === "denied" ? "This role cannot mutate the selected domain alert." : "The lifecycle advanced in order; prior events remain immutable."}</span></div>}<ol className="timeline">{selectedAlertEvents.map((alertEvent)=><li key={alertEvent.eventId}><span className="timeline-mark timeline-mark--done">✓</span><div><strong>{alertEvent.eventType}</strong><span>{alertEvent.actorId} · {alertEvent.reasonCode}</span><time>{alertEvent.occurredAt}</time></div></li>)}</ol><div className="pricing-integrity"><LockKeyhole size={15}/><span>{alertSummary.summary} Citations: {alertSummary.citations.join(" · ")}. AI cannot mutate alerts or linked cases.</span></div></aside></div></section>}
